function background(path) { ui.detail.style.backgroundImage = `linear-gradient(90deg, rgba(9,16,25,.18), rgba(9,16,25,.76)), url("${asset(path || scenario.defaults?.background)}")`; ui.detail.style.backgroundSize = 'cover'; ui.detail.style.backgroundPosition = 'center'; }
function renderPerson(character) { background(character.background); const header = document.createElement('div'); header.className = 'detail-topline'; header.textContent = 'PERSONNEL FILE / 聞き込み対象'; const card = document.createElement('div'); card.className = 'detail-card'; const portrait = document.createElement('div'); portrait.className = 'portrait'; const image = document.createElement('img'); image.src = asset(character.icon || scenario.defaults?.characterIcon); image.alt = character.name; portrait.append(image); const copy = document.createElement('div'); copy.className = 'detail-copy'; const role = document.createElement('div'); role.className = 'detail-role'; role.textContent = character.role || ''; const name = document.createElement('h2'); name.textContent = character.name; const description = document.createElement('p'); description.className = 'detail-description'; description.textContent = character.description || ''; copy.append(role, name, description); const characterConversations = scenario.conversations.filter((entry) => entry.nodes?.some((node) => node.speakerId === character.id) && available(entry.requires)); const nextConversation = characterConversations.find((entry) => !state.completedEvents.includes(entry.id) && !state.completedEvents.includes(entry.completionEventId)) || characterConversations[0]; if (nextConversation) copy.append(button('action-button', '話をする', () => openConversation(nextConversation))); card.append(portrait, copy); ui.detail.replaceChildren(header, card); }
function openCharacterConversation(characterId) { const candidates = scenario.conversations.filter((entry) => entry.nodes?.some((node) => node.speakerId === characterId) && available(entry.requires)); const next = candidates.find((entry) => !state.completedEvents.includes(entry.id) && !state.completedEvents.includes(entry.completionEventId)); if (next) openConversation(next); }function renderEvidenceDetail(item) { background(item.background); const header = document.createElement('div'); header.className = 'detail-topline'; header.textContent = 'EVIDENCE FILE / 証拠品'; const card = document.createElement('div'); card.className = 'detail-card'; const portrait = document.createElement('div'); portrait.className = 'portrait evidence-art'; if (item.icon || scenario.defaults?.evidenceIcon) { const image = document.createElement('img'); image.src = asset(item.icon || scenario.defaults.evidenceIcon); image.alt = item.name; portrait.append(image); } else portrait.textContent = 'EV'; const copy = document.createElement('div'); copy.className = 'detail-copy'; const name = document.createElement('h2'); name.textContent = item.name; const description = document.createElement('p'); description.className = 'detail-description'; description.textContent = item.description || ''; const action = button('action-button', '証拠品を調べる', () => startInvestigation(item)); copy.append(name, description, action); card.append(portrait, copy); ui.detail.replaceChildren(header, card); }
function showLogResult(text, title = 'ログ解析') { conversationSession = { transient: true, conversation: { id: `message_${Date.now()}`, title, nodes: [{ id: 'result', speakerId: 'narrator', text }] }, nodeId: 'result' }; renderDialogue(); }
function renderLog(log) { ui.detail.style.backgroundImage = 'none'; const header = document.createElement('div'); header.className = 'detail-topline'; header.textContent = 'LOG FILE / ログ調査'; const title = document.createElement('h2'); title.className = 'log-title'; title.textContent = log.name; const view = document.createElement('div'); view.className = 'log-view'; view.append(title); if (analyzingLogId !== log.id) { view.append(button('action-button', 'ログを解析する', () => { analyzingLogId = log.id; render(); }, false)); } else { for (const rowData of log.rows || []) { const checked = state.completedLogRows.includes(rowData.id); const discovered = state.discoveredLogRows.includes(rowData.id); const row = document.createElement('button'); row.type = 'button'; row.className = `log-row${discovered ? ' is-discovered' : ''}`; const flag = document.createElement('span'); flag.className = `question-flag${discovered ? ' is-discovered' : ''}`; flag.textContent = discovered ? '✓' : (rowData.important && !checked ? '?' : ''); const text = document.createElement('span'); text.textContent = `${rowData.time || ''}  ${rowData.text}`; row.append(flag, text); const selectable = Boolean(rowData.important) && (!checked || discovered); row.disabled = !selectable; if (selectable) { const action = document.createElement('span'); action.className = 'log-action-label'; action.textContent = discovered ? '結果を見る' : '解析する'; row.append(action); row.addEventListener('click', () => { if (!checked) state.completedLogRows.push(rowData.id); if (rowData.completionEventId) { if (!state.discoveredLogRows.includes(rowData.id)) state.discoveredLogRows.push(rowData.id); applyEvent(rowData.completionEventId); } save(); render(); showLogResult(rowData.completionEventId ? (rowData.result || 'ログから新しい情報が得られました。') : 'この行からは、捜査に役立つ情報は何も得られなかった。'); }); } view.append(row); } } ui.detail.replaceChildren(header, view); }function renderCollectionLanding() { ui.detail.style.backgroundImage = `linear-gradient(90deg, rgba(9,16,25,.2), rgba(9,16,25,.78)), url("${asset(scenario.defaults?.background)}")`; const names = { evidence: ['証拠品', 'EV'], logs: ['ログ', 'LOG'], facts: ['判明事項', '報'] }; const [title, icon] = names[state.activeTab]; ui.detail.innerHTML = `<div class="detail-topline">CASE FILES / ${title}</div><div class="detail-card"><div class="portrait evidence-art collection-placeholder">${icon}</div><div class="detail-copy"><div class="detail-role">資料一覧</div><h2>${title}</h2><p class="detail-description">右の「捜査資料」ペインから${title}を選択してください。</p></div></div>`; }
function renderDetail() { if (['evidence', 'logs', 'facts'].includes(state.activeTab) && !state.selectedEvidenceId && !state.selectedFactId && !state.selectedCharacterId) return renderCollectionLanding(); if (state.activeTab === 'facts' && !state.selectedCharacterId) { const fact = find('facts', state.selectedFactId); ui.detail.style.backgroundImage = ''; if (fact && state.facts.includes(fact.id)) { ui.detail.innerHTML = `<div class="detail-topline">INVESTIGATION REPORT / 捜査報告書</div><article class="fact-report"><div class="report-label">判明事項</div><h2></h2><p></p></article>`; ui.detail.querySelector('h2').textContent = fact.name; ui.detail.querySelector('p').textContent = fact.description || ''; } return; } const log = state.activeTab === 'logs' && !state.selectedCharacterId ? find('logs', state.selectedEvidenceId) : null; if (log) return renderLog(log); const evidence = !state.selectedCharacterId ? find('evidence', state.selectedEvidenceId) : null; if (evidence && state.evidence.includes(evidence.id)) return renderEvidenceDetail(evidence); const character = find('characters', state.selectedCharacterId) || scenario.characters[0]; if (character) { state.selectedCharacterId = character.id; renderPerson(character); } }
function render() { renderPeople(); renderEvidence(); renderDetail(); renderDialogue(); }
function startInvestigation(item) { const nodes = [{ id: 'intro', speakerId: 'narrator', text: `${item.name}を調べます。確認する項目を選んでください。`, choices: (item.investigations || []).map((investigation) => ({ text: investigation.label, nextNodeId: `investigation_${investigation.id}`, investigation })) }, ...(item.investigations || []).map((investigation) => ({ id: `investigation_${investigation.id}`, speakerId: 'narrator', text: investigation.description || `${investigation.label}を確認しました。` }))]; conversationSession = { conversation: { id: `investigation_${item.id}`, title: `${item.name}の調査`, nodes }, nodeId: 'intro', investigationItem: item }; renderDialogue(); }function openConversation(conversation) { conversationSession = { conversation, nodeId: conversation.startNodeId }; renderDialogue(); }
function finishConversation() { const session = conversationSession; const conversation = session?.conversation; if (conversation && !session.transient) { applyEvent(conversation.completionEventId); if (!state.completedEvents.includes(conversation.id)) state.completedEvents.push(conversation.id); } conversationSession = null; render(); save(); toast(session?.transient ? '確認を終了しました' : '会話を記録しました'); }
function showDialogueControls(node, conversation) { ui.dialogueChoices.replaceChildren(); ui.dialogueChoices.hidden = true; const visibleChoices = (node.choices || []).filter((choice) => available(choice.requires)); if (visibleChoices.length) { ui.dialogueChoices.hidden = false; visibleChoices.forEach((choice) => ui.dialogueChoices.append(button('action-button', choice.text, () => { if (choice.investigation) { const investigation = choice.investigation; if (!state.examinedInvestigations.includes(investigation.id)) { state.examinedInvestigations.push(investigation.id); applyEvent(investigation.completionEventId); save(); } } if (choice.nextNodeId) { conversationSession.nodeId = choice.nextNodeId; renderDialogue(); } else finishConversation(); }))); } else { const next = node.nextNodeId ? '次へ' : '会話を終了'; ui.dialogueChoices.hidden = false; ui.dialogueChoices.append(button('action-button', next, () => { if (node.nextNodeId) { conversationSession.nodeId = node.nextNodeId; renderDialogue(); } else finishConversation(); })); } }
function renderDialogue() { if (!conversationSession) { const keepForLogAnalysis = state?.activeTab === 'logs' && analyzingLogId; ui.dialogue.hidden = !keepForLogAnalysis; ui.dialogueChoices.hidden = true; ui.dialogueTitle.textContent = 'セリフ・調査結果'; ui.dialogueSpeaker.textContent = ''; ui.dialogueIcon.replaceChildren(); ui.dialogueText.classList.remove('is-typing'); ui.dialogueText.textContent = keepForLogAnalysis ? 'ログの行を選択すると、解析結果がここに表示されます。' : ''; clearTimeout(typingTimer); return; } const { conversation } = conversationSession; let node = findNode(conversation, conversationSession.nodeId); while (node?.routes?.length) { const route = node.routes.find((entry) => available(entry.requires)); if (!route) { conversationSession = null; renderDialogue(); return; } node = route.nextNodeId ? findNode(conversation, route.nextNodeId) : null; if (node) conversationSession.nodeId = node.id; } if (!node) { finishConversation(); return; } ui.dialogue.hidden = false; ui.dialogueChoices.hidden = true; ui.dialogueTitle.textContent = conversation.title || ''; const speaker = find('characters', node.speakerId); ui.dialogueSpeaker.textContent = speaker?.name || (node.speakerId === 'player' ? 'プレイヤー' : node.speakerId === 'narrator' ? 'ナレーション' : node.speakerId || ''); ui.dialogueIcon.replaceChildren(); const iconPath = node.icon || speaker?.icon; if (iconPath) { const image = document.createElement('img'); image.src = asset(iconPath); image.alt = ''; ui.dialogueIcon.append(image); } else if (speaker) ui.dialogueIcon.textContent = speaker.name.slice(0, 1); const fullText = node.text || ''; ui.dialogueText.textContent = ''; ui.dialogueText.classList.add('is-typing'); clearTimeout(typingTimer); const token = ++typingToken; let index = 0; const reveal = () => { if (token !== typingToken) return; index += 1; ui.dialogueText.textContent = fullText.slice(0, index); if (index < fullText.length) typingTimer = setTimeout(reveal, 35); else { ui.dialogueText.classList.remove('is-typing'); typingTimer = setTimeout(() => showDialogueControls(node, conversation), 350); } }; reveal(); }function findNode(conversation, id) { return (conversation.nodes || []).find((node) => node.id === id); }
async function start() { const response = await fetch('./case001.json'); if (!response.ok) throw new Error('シナリオデータを読み込めませんでした'); scenario = await response.json(); try { state = { ...DEFAULT_STATE, ...JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') }; } catch { state = clone(DEFAULT_STATE); } state.evidence = state.evidence.filter((id) => find('evidence', id)); state.logs = (state.logs || []).filter((id) => find('logs', id)); state.completedLogRows = (state.completedLogRows || []).filter((id) => scenario.logs.some((log) => log.rows?.some((row) => row.id === id))); state.discoveredLogRows = (state.discoveredLogRows || []).filter((id) => scenario.logs.some((log) => log.rows?.some((row) => row.id === id))); for (const log of scenario.logs) for (const row of log.rows || []) if (row.completionEventId && state.completedLogRows.includes(row.id) && !state.discoveredLogRows.includes(row.id)) state.discoveredLogRows.push(row.id); state.facts = state.facts.filter((id) => find('facts', id)); document.querySelectorAll('.tab-button').forEach((tab) => tab.addEventListener('click', () => { clearDialogue(); analyzingLogId = null; state.activeTab = tab.dataset.tab; state.selectedEvidenceId = null; state.selectedFactId = null; state.selectedCharacterId = null; render(); save(); })); document.querySelector('#inspection-close').addEventListener('click', () => ui.dialog.close()); document.querySelector('#dialogue-close').addEventListener('click', () => { conversationSession = null; renderDialogue(); }); document.querySelector('#save-button').addEventListener('click', () => { save(); toast('保存しました'); }); document.querySelector('#reset-button').addEventListener('click', () => { localStorage.removeItem(STORAGE_KEY); state = clone(DEFAULT_STATE); conversationSession = null; render(); save(); toast('試作データをリセットしました'); }); render(); save(); }
start().catch((error) => { ui.detail.textContent = error.message; ui.saveStatus.textContent = '読み込みに失敗'; });















